<script setup lang="ts">
/**
 * pages/evaluation.vue
 * ---------------------------------------------------------------------------
 * หน้าแบบประเมิน "ท่านชอบฐานใดมากที่สุด?" — เลือกได้ 1 จากฐานทั้งหมด (แสดงชื่อ
 * จริง จำนวน/ลำดับมาจาก Backend ไม่ hardcode ว่ามี 4 ฐาน) เข้ามาจากปุ่ม "จบเกม"
 * ที่หน้าฐานสุดท้าย (ดู pages/station/[stationId].vue::handleEndGame()) กด
 * "ส่งแบบประเมิน" แล้วพาไปหน้าสรุปผล/รางวัลเดิมของโปรเจกต์
 * (pages/round-summary.vue — ดูเหตุผลที่ใช้หน้านี้แทนที่จะสร้างหน้า Reward ใหม่
 * ในคอมเมนต์ handleSubmit ด้านล่าง)
 *
 * ใช้ submitSurvey() จริงของระบบเดิม (server-gas/SurveyService.gs — ระบบ Survey
 * นี้เป็นระบบที่ไม่แตะ/ไม่แก้ ไม่ได้ถูก sync กับ backend ล่าสุด) เฉพาะฝั่ง Online
 * เท่านั้น — favoriteStationRating ส่งเป็น "ลำดับ (order)" ของฐานที่เลือกตรง ๆ
 * (แทน mapping ตายตัว corn=1/soil=2/cow=3/milk=4 เดิม ซึ่งผูกกับ 4 ฐานคงที่)
 * ไม่ได้สร้าง API ใหม่ใด ๆ ฝั่ง Offline ไม่มี Round ฝั่ง Backend ให้บันทึกอยู่แล้ว
 * จึงเก็บแค่ในเครื่อง ไม่ Submit ไม่สำเร็จก็ไม่บล็อกผู้เล่น (รอบนี้เป็น Feedback
 * เสริม ไม่ใช่เงื่อนไขบังคับ)
 */
import { getStationVisual } from "~/composables/useAdventure";

definePageMeta({ layout: "app" });
const { profile, isReady } = useRequireProfile();
const { stations } = useAdventure();
const { isOfflineMode, endRound } = useOfflineMode();
const { currentRoundId, endCurrentRound } = useRound();
const { submitSurvey } = useMemberApi();
const { saveRoundSummary } = useRoundSummary();
const { setFavoriteStation, initStationQuest } = useStationQuest();
// [แก้ไข] "ฐานที่เล่นครบภารกิจแล้ว" ตอนนี้มาจาก composables/useStationMissions.ts
// (Backend เป็นเจ้าของความจริง) แทน useStationQuest() เดิม (mockScore/
// getStationMissions ที่นี่ถูกลบไปแล้ว — คะแนนรวมของรอบตอนนี้ pages/
// round-summary.vue ดึงจาก useRoundScores() เองแทน ไม่ต้องส่งสำเนามาทางนี้อีก)
const { isStationMissionComplete, initStationMissions } = useStationMissions();

/** เรียกซ้ำเพื่อความปลอดภัย (ปกติหน้าฐานสุดท้ายที่พามาถึงนี่โหลดไปแล้ว) —
 * กันเคส Hard Refresh ตรงหน้านี้เอง (ดู composables/useStationQuest.ts) —
 * initStationMissions() ก็เช่นกัน (restore Cache ของทุกฐานที่เคยเข้ามาในรอบนี้
 * ไม่ใช่แค่ฐานสุดท้ายที่พามาถึงหน้านี้) */
onMounted(async () => {
  await initStationQuest();
  initStationMissions();
});

const stationChoices = computed(() =>
  stations.value.map((s, index) => ({
    id: s.id,
    name: s.name,
    icon: getStationVisual(index).icon,
    order: s.order,
  })),
);

const selectedFavoriteStationId = ref<string | null>(null);
const submitting = ref(false);

function selectStation(id: string): void {
  if (submitting.value) return;
  selectedFavoriteStationId.value = id;
}

/**
 * กด "ส่งแบบประเมิน" — เก็บฐานที่เลือกไว้ในเครื่องเสมอ (setFavoriteStation) แล้ว
 * ปิด Round ตามช่องทางเดิมของระบบ (Online: submitSurvey() + endCurrentRound() /
 * Offline: endRound()) ก่อนเก็บสรุปผล "รอบนี้" ด้วยข้อมูล Mock (ฐานที่ทำครบ 3/3
 * + mockScore) ผ่าน useRoundSummary เดิม แล้วพาไป /round-summary
 *
 * [Fix — root cause ของ "หน้าสรุปผลขึ้น 0 คะแนน/ไม่มีฐานที่เล่นเลย ทั้งที่เพิ่งเล่น
 * ครบ 4 ฐาน"] เดิมอ่าน completedStations/mockScore "หลัง" เรียก endCurrentRound()
 * ไปแล้ว — endCurrentRound() เคลียร์ currentRoundId เป็น null ใน finally ของมันเอง
 * เสมอ ซึ่งเปลี่ยน effectiveRoundKey ใน useStationQuest.ts ทันที (จาก
 * "online:<roundId>" เป็น "no-round") ไป Trigger watch(effectiveRoundKey) ที่นั่น
 * ให้เข้าใจว่า "เปลี่ยนรอบใหม่แล้ว" แล้วล้าง Progress/mockScore ทั้งหมดทิ้งทันที
 * ก่อนที่โค้ดด้านล่างจะทันได้อ่านค่าจริงเสียอีก (อ่านได้ค่าว่างเปล่าเสมอ) แก้โดย
 * จับค่าสรุปผลทั้งหมด (completedStations/correctCount/mockScore) ไว้ "ก่อน" เรียก
 * endCurrentRound()/submitSurvey()/endRound() เสมอ — เหมือนที่ต้องจับ roundId ไว้
 * ก่อนด้วยเหตุผลเดียวกัน (ดู pages/scan.vue เดิม)
 */
async function handleSubmit(): Promise<void> {
  if (!selectedFavoriteStationId.value || submitting.value) return;
  submitting.value = true;
  try {
    setFavoriteStation(selectedFavoriteStationId.value);

    const roundIdForSummary = currentRoundId.value;
    const userIdForSummary = profile.value?.memberId || profile.value?.uid || null;
    let startTimeIso: string | null = null;
    let endTimeIso = new Date().toISOString();

    // [Fix] จับค่าสรุปผลไว้ก่อนเสมอ ก่อนเรียกอะไรที่อาจทำให้ Round เปลี่ยน/จบ (ดู
    // คอมเมนต์ด้านบน) — เหลือแค่ชื่อฐานที่เล่นครบภารกิจแล้ว (คะแนนรวมจริงของรอบนี้
    // pages/round-summary.vue ดึงจาก useRoundScores() เองแทน ไม่ต้องคำนวณ/ส่ง
    // สำเนามาทางนี้อีกต่อไป)
    const completedStations = stationChoices.value
      .filter((s) => isStationMissionComplete(s.id))
      .map((s) => ({ name: s.name, points: 0 }));
    const selectedStation = stationChoices.value.find(
      (s) => s.id === selectedFavoriteStationId.value,
    );

    if (isOfflineMode.value) {
      endRound();
    } else if (profile.value?.memberId && roundIdForSummary) {
      try {
        await submitSurvey({
          roundId: roundIdForSummary,
          userId: profile.value.memberId,
          firstName: profile.value.firstName,
          favoriteStationRating: selectedStation?.order ?? 1,
        });
      } catch (err) {
        console.error("[evaluation] submitSurvey failed", err);
      }
      const ended = await endCurrentRound(profile.value.memberId);
      if (ended) {
        startTimeIso = ended.startTime || null;
        endTimeIso = ended.endTime || endTimeIso;
      }
    }

    saveRoundSummary({
      mode: isOfflineMode.value ? "offline" : "online",
      startTime: startTimeIso,
      endTime: endTimeIso,
      stations: completedStations,
      totalPoint: null,
      roundId: isOfflineMode.value ? null : roundIdForSummary,
      userId: userIdForSummary,
      endedReason: "manual",
    });
  } finally {
    submitting.value = false;
  }
  await navigateTo("/round-summary");
}
</script>

